    # In demos markers occupy a cell of a 3x3 block; the repeated shape is the
    # set of 1-cells within a connected 1-object. Extract marker-to-block via
    # 8-connectivity, then match the colored cell's relative position in every
    # other 3x3 all-1 (or sparse matching) motif.
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,1): continue
        # Build the marker's contiguous local object from all 1/color cells.
        q=deque([(r,c)]); seen={(r,c)}; comp=[]
        while q:
          y,x=q.popleft(); comp.append((y,x))
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              ny,nx=y+dy,x+dx
              if 0<=ny<h and 0<=nx<w and grid[ny][nx] in (1,color) and (ny,nx) not in seen:
