        # Marker objects encode a local 3x3 colored pattern by their colored
        # positions; here the clue itself is a single coordinate. It is copied
        # to each repeated 3x3 component with corresponding 1 at that offset.
        # Use structural similarity of 3x3 neighborhoods around seed and target.
        for oy in range(max(0,r-2),min(r+1,h-2)):
          for ox in range(max(0,c-2),min(c+1,w-2)):
            dy,dx=r-oy,c-ox
            src=[[1 if (oy+i==r and ox+j==c) else grid[oy+i][ox+j] for j in range(3)] for i in range(3)]
